INSERT INTO ANALYSE (ID_DOCUMENT, NUM_ANALYSE, PM, AM1, AM2, AM3, AM4, AM5, AM6, AM7, AM8, AM9, AM10, AM11, AM12, SOMMAIRE, TITRE_REFERENCE) VALUES(${SOURCEID}, 1, 'STATUTS PROFESSIONNELS PARTICULIERS*', 'Journaliste professionnel', 'Contrat de travail', 'Résiliation', 'cas', 'Salariés d''entreprises de presse', 'Application des dispositions du code du travail', 'Condition', 'Détermination', 'Portée', NULL, NULL, NULL, 'Il résulte de la combinaison des articles L. 7111-1, L. 7111-3, L. 7111-5 et L. 7112-5 du code du travail que les dispositions de ce dernier texte peuvent être invoquées par les journalistes exerçant leur profession dans une ou plusieurs entreprises de presse, quelles qu''elles soient, notamment dans une ou plusieurs entreprises de communication au public par voie électronique, lorsque la résiliation du contrat de travail a été motivée par l''une des circonstances qu''il énumère', NULL);
INSERT INTO ANALYSE (ID_DOCUMENT, NUM_ANALYSE, PM, AM1, AM2, AM3, AM4, AM5, AM6, AM7, AM8, AM9, AM10, AM11, AM12, SOMMAIRE, TITRE_REFERENCE) VALUES(${SOURCEID}, 2, 'STATUTS PROFESSIONNELS PARTICULIERS*', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Il résulte de la combinaison des articles L.7111-1, L.7111-5 et L. 7112-5 du code du travail que lorsque la rupture du contrat de travail survient à l''initiative du journaliste professionnel et qu''elle est motivée par la cession de l''entreprise de communication au public par voie électronique au service de laquelle il exerce sa profession, les dispositions des articles L. 7112-3 et L. 7112-4 sont applicables', NULL);
INSERT INTO TITREREFERENCE (ID_DOCUMENT, NUM_ANALYSE, NUM_TITREREFERENCE, PM, AM1, AM2, AM3, AM4, AM5, AM6, AM7, AM8, AM9, AM10, AM11, AM12) VALUES(${SOURCEID}, 1, 1, 'STATUTS PROFESSIONNELS PARTICULIERS*', 'Journaliste professionnel', 'Statut', 'Application', 'Conditions', 'Cas', 'Salarié d''une entreprise de communication au public par voie électronique', 'Application des dispositions du code du travail', 'Caractère suffisant', 'Portée', NULL, NULL, NULL);
INSERT INTO TITREREFERENCE (ID_DOCUMENT, NUM_ANALYSE, NUM_TITREREFERENCE, PM, AM1, AM2, AM3, AM4, AM5, AM6, AM7, AM8, AM9, AM10, AM11, AM12) VALUES(${SOURCEID}, 1, 2, 'PRESSE*', 'Journal', 'Journaliste professionnel', 'Statut', 'Application', 'Condition', NULL, NULL, NULL, NULL, NULL, NULL, NULL);